export const CompositeCard = ({
  card,
  cardIndex,
  submitted,
  submissionLocked = false,
  partStates,
  showSubmit = true,
  showResult = true,
  revealCorrectness,
  showSolution,
  forceRevealText = false,
  helpText,
  helpEnabled,
  onBlankDragOver,
  onClozeInputChange,
