  submissionLocked?: boolean;
  showSubmit?: boolean;
  showResult?: boolean;
  revealCorrectness?: boolean;
  showSolution?: boolean;
  helpText?: string[] | string;
  helpEnabled?: boolean;
  onSelect: (cardIndex: number, itemId: string, value: TrueFalseSelection) => void;
