              <span className="label">Hint {index + 1}</span>
            ) : null}
            <div className="help-markdown exam-markdown">
              <ReactMarkdown
                remarkPlugins={[remarkGfm]}
                rehypePlugins={[[rehypeSanitize, markdownSchema]]}
              >
                {block}
              </ReactMarkdown>
            </div>
          </section>
        ))}
      </div>
      {onClose ? (
