const buildCompositeCard = (): Flashcard => ({
  kind: "composite",
  parts: [
    {
      kind: "multiple-choice",
      question: "Pick one",
      options: [
        { key: "a", text: "A" },
        { key: "b", text: "B" },
      ],
      correctKeys: ["a"],
    },
  ],
