  flex-direction: column;
}

.tree-item {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  flex-wrap: nowrap;
  gap: 6px;
  padding: 5px 8px;
  padding-left: calc(8px + var(--tree-indent, 0px));
  border-radius: 6px;
  background: var(--accent-weak-bg);
  border: 1px solid transparent;
  font-weight: 600;
  font-size: 0.8rem;
  color: var(--ink);
  cursor: pointer;
  text-align: left;
  transition: 0.2s ease;
  min-width: 0;
