.tree-item.is-hidden {
  opacity: var(--hidden-item-opacity, 0.6);
}

.tree-item:hover {
  border-color: var(--accent-border);
}

.tree-item.active {
  border-color: var(--accent-border);
  background: var(--accent-active-bg);
}

.tree-item.breadcrumb {
  border-color: var(--line-soft);
}

.tree-item.active-folder {
  border-color: var(--accent-strong);
  background: var(--accent-active-bg);
  font-weight: 700;
}

.vault-tree-scroll.vault-tree-scroll-wide .tree-item {
  min-width: calc(100% + var(--tree-overflow, 0px));
}

.tree-dir summary {
  list-style: none;
  display: flex;
  align-items: center;
}

.tree-dir summary::-webkit-details-marker {
  display: none;
}

.tree-dir summary::after {
  content: ">";
  margin-left: auto;
  color: var(--muted);
  font-size: 0.7rem;
  transition: transform 0.2s ease;
}

.tree-dir[open] summary::after {
  transform: rotate(90deg);
}

.tree-children {
  margin-left: 0;
  padding-left: 0;
  padding-top: 6px;
  border-left: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tree-icon {
  width: 14px;
  height: 14px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  color: var(--accent);
}

.tree-icon svg {
  width: 12px;
  height: 12px;
}

.tree-file {
  background: var(--panel);
  width: calc(100% - 8px);
}

.vault-tree-scroll.vault-tree-scroll-wide .tree-file {
  min-width: calc(100% + var(--tree-overflow, 0px) - 8px);
}

.tree-name {
  flex: 1;
  min-width: 0;
  line-height: 1.2;
  max-height: calc(1.2em * 2);
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  text-overflow: ellipsis;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.context-menu-backdrop {
  position: fixed;
  inset: 0;
  z-index: 60;
}

.context-menu {
  position: fixed;
  min-width: 180px;
  background: var(--panel);
  border: 1px solid var(--line-soft);
  border-radius: 12px;
  padding: 6px;
