/*
 * @file apps/fmd-desktop/src/styles/components/flashcards.css
 *
 * Zweck:
 * - Definiert Styles fuer flashcards.
 *
 * Verantwortlichkeiten:
 * - Layout- und Komponenten-Styles fuer flashcards.
 * - Zustands- und Variantenklassen fuer Interaktionen.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/App.css: Nutzt dieses Modul.
 * - apps/fmd-desktop/src/styles/tokens.css: Design-Tokens und Variablen.
 *
 * Hinweise:
 * - Nutzt CSS-Variablen aus styles/tokens.css fuer konsistente Farben und Abstaende.
 */

.flashcard-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.flashcard-item {
  padding: 14px;
  border-radius: 16px;
  background: var(--block-bg);
  border: 1px solid var(--block-border);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.composite-card {
  gap: 16px;
}

.composite-parts {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.composite-card .flashcard-item {
  background: var(--panel);
}

.flashcard-question {
  margin: 0;
  font-size: 1rem;
  font-weight: 700;
}

.flashcard-options {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.truefalse-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.truefalse-item {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  border-radius: 12px;
  border: 1px solid var(--line-soft);
  background: var(--panel);
}

.truefalse-question {
  font-weight: 600;
  color: var(--ink);
}

.truefalse-options {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.truefalse-option {
  border: 1px solid var(--line-soft);
  border-radius: 999px;
  padding: 6px 12px;
  background: var(--accent-weak-bg);
  color: var(--ink);
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s ease;
}

.truefalse-option.selected {
  border-color: var(--accent-border);
  background: var(--accent-soft);
}

.truefalse-option.correct {
  border-color: var(--accent-strong);
  background: var(--accent-soft);
}

.truefalse-option.incorrect {
  border-color: var(--error-border);
  background: var(--error-bg);
}

.truefalse-option:disabled {
  cursor: not-allowed;
  opacity: 0.7;
}

.truefalse-result {
  font-size: 0.8rem;
  font-weight: 600;
}

.truefalse-result.correct {
